def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    s_high = str(high)
    s_low = str(low - 1)

    @lru_cache(None)
    def count_beautiful(s: str) -> int:
        n = len(s)
        # dp state: (index, current_remainder, diff_even_odd, is_less, is_started)
        # diff_even_odd: positive means more even digits, negative means more odd
        memo = {}

        def solve(idx, rem, diff, is_less, is_started):
            state = (idx, rem, diff, is_less, is_started)
            if state in memo: return memo[state]

            if idx == n:
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            limit = int(s[idx]) if not is_less else 9

            for d in range(limit + 1):
                new_is_less = is_less or (d < limit)
                new_is_started = is_started or (d > 0)

                if not new_is_started:
                    res += solve(idx + 1, 0, 0, new_is_less, False)
                else:
                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    new_rem = (rem * 10 + d) % k
                    res += solve(idx + 1, new_rem, new_diff, new_is_less, True)

            memo[state] = res
            return res

        # Since we need to handle different lengths implicitly via "is_started",
        # but the string length matters for total count logic, we use a simpler 
        # approach: call solve on string of same length as s.
        # The 'is_started' flag handles leading zeros correctly.
        return solve(0, 0, 0, False, False)

    # Because the DP above is slightly complex with leading zeros for different lengths,
    # a more robust way to handle "all numbers <= X" is to sum up counts for all 
    # possible lengths shorter than len(s_high), and then the count for len(s_high).

    def get_count(limit_str: str) -> int:
        n = len(limit_str)
        @lru_cache(None)
        def dp(idx, rem, diff, is_less, is_started):
            if idx == n:
                return 1 if is_started and diff == 0 and rem == 0 else 0

            res = 0
            upper = int(limit_str[idx]) if not is_less else 9
            for d in range(upper + 1):
                next_is_less = is_less or (d < upper)
                if not is_started and d == 0:
                    res += dp(idx + 1, 0, 0, next_is_less, False)
                else:
                    new_diff = diff + (1 if d % 2 == 0 else -1)
                    res += dp(idx + 1, (rem * 10 + d) % k, new_diff, next_is_less, True)
            return res

        # Clear cache for different limit strings or handle carefully.
        # To be safe and fast, we just clear it.
        dp.cache_clear()
        return dp(0, 0, 0, False, False)

