def count(num1: str, num2: str, min_sum: int, max_sum: int):
    MOD = 10**9 + 7

    # 輔助函式：計算從 0 到 s 的數字中，位元和在 [min_s, max_s] 之間的數量
    def count_upto(s: str, min_s: int, max_s: int) -> int:
        n = len(s)
        # memo[index][current_sum][is_less]
        memo = {}

        def dp(idx, current_sum, is_less):
            if current_sum > max_s:
                return 0
            if idx == n:
                return 1 if min_s <= current_sum <= max_s else 0

            state = (idx, current_sum, is_less)
            if state in memo:
                return memo[state]

            limit = int(s[idx]) if not is_less else 9
            res = 0
            for d in range(limit + 1):
                res = (res + dp(idx + 1, current_sum + d, is_less or (d < limit))) % MOD

            memo[state] = res
            return res

        return dp(0, 0, False)

    # 計算 num2 的結果
    ans2 = count_upto(num2, min_sum, max_sum)

    # 計算 num1 - 1 的結果 (處理字串減法)
    # 因為 num1 可能很大，直接轉 int 再轉 str 是最簡單且符合 Python 特性的做法
    val1 = int(num1) - 1
    if val1 < 0:
        ans1 = 0
    else:
        ans1 = count_upto(str(val1), min_sum, max_sum)

    return (ans2 - ans1 + MOD) % MOD
